"use strict";
import ConnectWalletLanding from "components/ConnectWalletLanding";
import { useAccount } from "hooks/useAccount";
import { Flex } from "ui/src";
import { IncentivizeProvider, useIncentivizeContext } from "./ContextProvider";
import IncentivizePoolFirstStep from "./components/IncentivizePoolFirstStep";
import IncentivizePoolSecondStep from "./components/IncentivizePoolSecondStep";
import IncentivizePoolThirdStep from "./components/IncentivizePoolThirdStep";
const Incentivize = () => {
  const { incentivizeStep } = useIncentivizeContext();
  return <Flex
    mt="$spacing24"
    width="100%"
    px="$spacing40"
    maxWidth={780}
    pb={"$spacing40"}
    $xl={{
      px: "$spacing12",
      mx: "auto"
    }}
    flexDirection="column"
    gap={"$gap12"}
  >
      {incentivizeStep === "step-1" && <IncentivizePoolFirstStep />}
      {incentivizeStep === "step-2" && <IncentivizePoolSecondStep />}
      {incentivizeStep === "step-3" && <IncentivizePoolThirdStep />}
    </Flex>;
};
const ConntextWrapper = () => {
  const { address } = useAccount();
  if (!address) {
    return <ConnectWalletLanding
      title="Connect Your Wallet"
      description="Connect your wallet to create liquidity pool incentives"
    />;
  }
  return <IncentivizeProvider>
      <Incentivize />
    </IncentivizeProvider>;
};
export default ConntextWrapper;
