"use strict";
import { useQuery } from "@tanstack/react-query";
import { useAccount } from "hooks/useAccount";
import { useVoterReads } from "./useVoterContract";
import { useAvailableGauges } from "./useGaugeData";
import { getAbstractSubgraphs } from "uniswap/src/constants/abstractContracts";
import { formatEther } from "viem";
async function fetchPoolVotingData(subgraphUrl, poolAddress) {
  const POOL_VOTES_QUERY = `
    query GetPoolVotes($poolAddress: String!) {
      gauges(where: { pool: $poolAddress }) {
        id
        pool
        totalWeight
        emissions
        poolType
      }
      
      votes(
        where: { gauge_: { pool: $poolAddress } }
        first: 1000
      ) {
        id
        weight
        tokenId
        gauge {
          id
          pool
        }
      }
    }
  `;
  try {
    const response = await fetch(subgraphUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        query: POOL_VOTES_QUERY,
        variables: { poolAddress: poolAddress.toLowerCase() }
      })
    });
    if (!response.ok) {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }
    const data = await response.json();
    if (data.errors) {
      console.error("GraphQL errors:", data.errors);
      throw new Error(`GraphQL errors: ${JSON.stringify(data.errors)}`);
    }
    const gauges = data.data?.gauges || [];
    const votes = data.data?.votes || [];
    if (gauges.length > 0) {
      const gauge = gauges[0];
      const totalVotesFromVotes = votes.reduce((sum, vote) => {
        const voteWeight = parseFloat(formatEther(BigInt(vote.weight || "0")));
        return sum + voteWeight;
      }, 0);
      const gaugeTotalWeight = parseFloat(formatEther(BigInt(gauge.totalWeight || "0")));
      const totalVotes = Math.max(gaugeTotalWeight, totalVotesFromVotes);
      return {
        poolAddress,
        totalVotes: totalVotes.toFixed(2),
        poolId: gauge.id
      };
    }
    return null;
  } catch (error) {
    console.error("Failed to fetch pool voting data:", error);
    return null;
  }
}
async function fetchEmissionsData(voterAddress, chainId) {
  if (!voterAddress || !chainId) return null;
  try {
    return {
      totalEmissions: "65988.4",
      emissionToken: "ABX",
      epochRewards: "65988.4"
    };
  } catch (error) {
    console.error("Failed to fetch emissions data:", error);
    return null;
  }
}
function calculateVotingDeadline(epochVoteEnd) {
  if (!epochVoteEnd) return null;
  const now = Math.floor(Date.now() / 1e3);
  const timeUntilDeadline = Math.max(0, epochVoteEnd - now);
  const daysUntilDeadline = Math.floor(timeUntilDeadline / (24 * 60 * 60));
  const hoursUntilDeadline = Math.floor(timeUntilDeadline % (24 * 60 * 60) / (60 * 60));
  const isVotingActive = timeUntilDeadline > 0;
  return {
    votingDeadlineTimestamp: epochVoteEnd,
    timeUntilDeadline,
    daysUntilDeadline,
    hoursUntilDeadline,
    isVotingActive
  };
}
export function useIncentiveData(selectedPoolAddress) {
  const { chainId } = useAccount();
  const { epochVoteEnd } = useVoterReads();
  const { data: availableGauges } = useAvailableGauges();
  const incentiveQuery = useQuery({
    queryKey: ["incentive-data", selectedPoolAddress, chainId, epochVoteEnd],
    queryFn: async () => {
      const subgraphs = chainId ? getAbstractSubgraphs(chainId) : null;
      const votingDeadline = calculateVotingDeadline(epochVoteEnd);
      const emissions = await fetchEmissionsData(subgraphs?.voter, chainId);
      if (!selectedPoolAddress) {
        const totalVotes = availableGauges?.reduce((sum, gauge) => {
          const gaugeWeight = parseFloat(formatEther(BigInt(gauge.totalWeight || "0")));
          return sum + gaugeWeight;
        }, 0) || 0;
        return {
          poolVoting: {
            poolAddress: "all",
            totalVotes: totalVotes.toFixed(2),
            tokenPair: "All Pools"
          },
          emissions,
          votingDeadline
        };
      }
      let poolVoting = null;
      if (subgraphs?.gauges) {
        poolVoting = await fetchPoolVotingData(subgraphs.gauges, selectedPoolAddress);
      }
      return {
        poolVoting,
        emissions,
        votingDeadline
      };
    },
    enabled: Boolean(chainId),
    staleTime: 3e4,
    refetchInterval: 6e4
  });
  return {
    poolVoting: incentiveQuery.data?.poolVoting || null,
    emissions: incentiveQuery.data?.emissions || null,
    votingDeadline: incentiveQuery.data?.votingDeadline || null,
    isLoading: incentiveQuery.isLoading,
    error: incentiveQuery.error?.message || null
  };
}
export function useSelectedPoolIncentiveData(selectedPool) {
  const poolAddress = selectedPool?.id || selectedPool?.pool || selectedPool?.address;
  return useIncentiveData(poolAddress);
}
