"use strict";
import { Check } from "react-feather";
import { Flex, Text, useSporeColors } from "ui/src";
import { useIncentivizeContext } from "../ContextProvider";
export default function PoolCheckOptions() {
  const colors = useSporeColors();
  const { selectedPoolType, setSelectedPoolType } = useIncentivizeContext();
  const CheckIcon = () => <Flex height={18} width={18} backgroundColor={"$neutral1"} centered borderRadius={"$roundedFull"}>
      <Check color={colors.surface1.val} size={15} />
    </Flex>;
  const poolOptions = [
    {
      title: "Concentrated Pools",
      text: "These pools require you to specify a price range in which your liquidity will be active. The range is defined using evenly spaced price intervals called ticks."
    },
    {
      title: "Basic Pools",
      text: "Also known as constant product AMMs, these pools spread liquidity across the full price range (0 to \u221E) and require little to no active management."
    }
  ];
  return <Flex
    $platform-web={{ display: "grid", gridTemplateColumns: "1fr 1fr" }}
    gap={"$gap24"}
    $lg={{ display: "none", gridTemplateColumns: "1fr" }}
  >
      {poolOptions.map((option, index) => <Flex
    key={option.title}
    p={"$spacing12"}
    borderWidth={1}
    borderColor={index === selectedPoolType ? "$neutral3" : "$surface3"}
    borderRadius={"$rounded12"}
    transition='background-color 0.2s ease'
    hoverStyle={{ backgroundColor: "$surface2" }}
    cursor="pointer"
    onPress={() => setSelectedPoolType((prev) => prev === index ? -1 : index)}
  >
          <Flex row justifyContent="space-between" gap={"$gap6"}>
            <Text variant="body2" fontWeight={"$medium"}>
              {option.title}
            </Text>
            {index === selectedPoolType && <CheckIcon />}
          </Flex>

          <Text mt={"$gap12"} variant="body3" color={"$neutral2"} wordWrap="break-word">
            {option.text}
          </Text>
        </Flex>)}
    </Flex>;
}
