"use strict";
import { DropdownButton, Flex, Text, useMedia } from "ui/src";
import { iconSizes } from "ui/src/theme";
import { TokenLogo } from "uniswap/src/components/CurrencyLogo/TokenLogo";
import { useCurrencyInfo } from "uniswap/src/features/tokens/useCurrencyInfo";
import { currencyId } from "uniswap/src/utils/currencyId";
export const CurrencySelector = ({
  currencyInfo,
  onPress,
  emphasis
}) => {
  const getCurrencyData = useCurrencyInfo(currencyId(currencyInfo)) || void 0;
  const currency = getCurrencyData?.currency;
  const media = useMedia();
  return <DropdownButton
    emphasis={emphasis}
    onPress={onPress}
    elementPositioning="grouped"
    isExpanded={false}
    py={"$spacing24"}
    $lg={{
      py: "$spacing20",
      px: "$spacing8"
    }}
  >
      <Flex row gap={"$spacing8"} alignItems="center">
        {currency && <TokenLogo
    size={media.lg ? iconSizes.icon18 : iconSizes.icon24}
    chainId={currency.chainId}
    name={currency.name}
    symbol={currency.symbol}
    url={getCurrencyData?.logoUrl}
  />}
        <Text variant={media.lg ? "buttonLabel3" : "buttonLabel2"} color={currency ? "$neutral1" : "$surface1"}>
          {currency ? currency.symbol : "Select token"}
        </Text>
      </Flex>
    </DropdownButton>;
};
